   276|async function requestIVXAIAnswer(input: {
   277|  message: string;
   278|  history: PublicChatHistoryItem[];
   279|  sessionId: string;
   280|  businessContext: string | null;
   281|  images: PublicChatImageAttachment[];
   282|  documents: DealDocumentAttachment[];
   283|  extractedDocuments: ExtractedDocument[];
   284|  videoUnderstandings: VideoUnderstanding[];
   285|}): Promise<PublicChatAnswerResult> {
   286|  const endpoint = getGatewayModelEndpoint();
   287|  if (!isPublicChatAIConfigured() || !endpoint) {
   288|    throw new Error('IVX AI proxy configuration is missing.');
   289|  }
   290|
   291|  const promptParts = [
   292|    'Recent public chat transcript:',
   293|    buildTranscript(input.history),
   294|    '',
   295|  ];
   296|  if (input.businessContext) {
   297|    promptParts.push(input.businessContext, '');
   298|  }
   299|  if (input.images.length > 0) {
   300|    promptParts.push(
   301|      `Note: ${input.images.length} image attachment(s) accompany this message — analyze them as part of your answer.`,
   302|      '',
   303|    );
   304|  }
   305|  if (input.documents.length > 0) {
   306|    promptParts.push(
   307|      `Note: ${input.documents.length} deal-room document(s) accompany this message: ${input.documents
   308|        .map((doc) => `${doc.name ?? doc.url} [${doc.kind}] ${doc.url}`)
   309|        .join('; ')}. Analyze them as an acquisition analyst per the instructions above.`,
   310|      '',
   311|    );
   312|  }
   313|  const extractedContentBlock = buildExtractedDocumentContentBlock(input.extractedDocuments);
   314|  if (extractedContentBlock) {
   315|    promptParts.push(extractedContentBlock, '');
   316|  }
   317|  const videoContentBlock = buildVideoUnderstandingBlock(input.videoUnderstandings);
   318|  if (videoContentBlock) {
   319|    promptParts.push(videoContentBlock, '');
   320|  }
   321|  promptParts.push(
   322|    `User message: ${input.message || (input.images.length > 0 ? 'Analyze the attached image(s).' : '')}`,
   323|    '',
   324|    'Reply directly to the user message. If the user asks for an exact token or proof string, include it exactly.',
   325|  );
   326|
   327|  const result = await requestIVXAIText({
   328|    module: 'public-chat',
   329|    requestId: input.sessionId,
   330|    model: getPublicChatModel(),
   331|    system: buildSystemPrompt(
   332|      input.sessionId,
   333|      input.images.length > 0,
   334|      input.documents,
   335|      extractedContentBlock,
   336|      videoContentBlock,
   337|    ),
   338|    prompt: promptParts.join('\n'),
   339|    images: input.images.length > 0 ? input.images : undefined,
   340|  });
   341|
   342|  return {
   343|    answer: result.text,
   344|    model: result.providerMetadata.model,
   345|    source: 'chatgpt',
   346|    endpoint: result.providerMetadata.endpoint,
   347|    imageCount: input.images.length,
   348|    providerMetadata: result.providerMetadata,
   349|  };
