cd /home/user/rork-app && echo "=== LATENCY MEASUREMENT — First token & complete response ===" && bun -e "
const start = Date.now();
const response = await fetch('https://ivx-holdings-platform.onrender.com/api/public/chat/stream', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'x-ivx-client-id': 'qa-latency' },
  body: JSON.stringify({ message: 'What are two benefits of compound interest?', sessionId: 'qa-latency-1', requestId: 'qa-latency-1', history: [] }),
});

const reader = response.body!.getReader();
const decoder = new TextDecoder();
let buffer = '';
let firstTokenTime = 0;
let lastTokenTime = 0;
let completeTime = 0;
let fullText = '';
let deltaCount = 0;

while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += decoder.decode(value, { stream: true });
  const events = buffer.split('\n\n');
  buffer = events.pop() ?? '';
  for (const evt of events) {
    const lines = evt.split('\n').filter(l => l.startsWith('data: '));
    for (const line of lines) {
      try {
        const payload = JSON.parse(line.slice(6));
        if (payload.type === 'response.delta' && payload.delta) {
          if (firstTokenTime === 0) firstTokenTime = Date.now();
          lastTokenTime = Date.now();
          fullText += payload.delta;
          deltaCount++;
        }
        if (payload.type === 'response.completed') {
          completeTime = Date.now();
        }
      } catch {}
    }
  }
}

const requestSentTime = start;
const firstTokenLatency = firstTokenTime - requestSentTime;
const completeLatency = completeTime - requestSentTime;
console.log('SEND TIME:', new Date(start).toISOString());
console.log('FIRST TOKEN LATENCY:', firstTokenLatency + 'ms');
console.log('COMPLETE RESPONSE LATENCY:', completeLatency + 'ms');
console.log('DELTA COUNT:', deltaCount);
console.log('RESPONSE LENGTH:', fullText.length);
console.log('STREAMING CONFIRMED:', firstTokenTime > 0 && lastTokenTime > firstTokenTime ? 'YES — tokens arrived progressively' : 'NO');
" 2>&1

